# Password Predictability Analyzer

Here's a comprehensive Python tool to measure the predictability of passwords:

```python
import re
import math
import string
from collections import Counter

# Common patterns and weak passwords
COMMON_PASSWORDS = {
    "password", "123456", "password123", "admin", "letmein",
    "qwerty", "abc123", "monkey", "1234567890", "iloveyou",
    "welcome", "login", "passw0rd", "master", "hello"
}

KEYBOARD_PATTERNS = [
    "qwerty", "qwertyuiop", "asdfgh", "asdfghjkl", "zxcvbn",
    "1234567890", "0987654321", "12345678", "87654321"
]

COMMON_SUBSTITUTIONS = {
    '@': 'a', '3': 'e', '1': 'i', '0': 'o', '5': 's',
    '$': 's', '7': 't', '4': 'a', '!': 'i', '+': 't'
}


def calculate_entropy(password: str) -> float:
    """Calculate Shannon entropy of a password."""
    if not password:
        return 0.0
    freq = Counter(password)
    length = len(password)
    entropy = -sum((count / length) * math.log2(count / length)
                   for count in freq.values())
    return round(entropy, 4)


def calculate_charset_size(password: str) -> int:
    """Determine the character set size used in the password."""
    charset = 0
    if any(c in string.ascii_lowercase for c in password):
        charset += 26
    if any(c in string.ascii_uppercase for c in password):
        charset += 26
    if any(c in string.digits for c in password):
        charset += 10
    if any(c in string.punctuation for c in password):
        charset += 32
    return charset


def calculate_brute_force_entropy(password: str) -> float:
    """Calculate entropy based on charset size and length."""
    charset_size = calculate_charset_size(password)
    if charset_size == 0:
        return 0.0
    return round(len(password) * math.log2(charset_size), 4)


def check_common_password(password: str) -> bool:
    """Check if password is in the common passwords list."""
    return password.lower() in COMMON_PASSWORDS


def check_keyboard_pattern(password: str) -> bool:
    """Check if password contains keyboard patterns."""
    lower = password.lower()
    return any(pattern in lower for pattern in KEYBOARD_PATTERNS)


def check_repeated_chars(password: str) -> float:
    """Calculate the ratio of repeated characters (0 = no repeats, 1 = all same)."""
    if not password:
        return 0.0
    unique_chars = len(set(password))
    return round(1 - (unique_chars / len(password)), 4)


def check_sequential_chars(password: str) -> int:
    """Count the number of sequential character runs (e.g., 'abc', '123')."""
    sequences = 0
    for i in range(len(password) - 2):
        a, b, c = ord(password[i]), ord(password[i+1]), ord(password[i+2])
        if (b - a == 1 and c - b == 1) or (a - b == 1 and b - c == 1):
            sequences += 1
    return sequences


def check_leet_speak(password: str) -> str:
    """Convert leet speak to plain text and check against common passwords."""
    decoded = password.lower()
    for symbol, letter in COMMON_SUBSTITUTIONS.items():
        decoded = decoded.replace(symbol, letter)
    return decoded


def check_number_padding(password: str) -> bool:
    """Check if password is a word with numbers padded at start/end."""
    return bool(re.match(r'^\d+[a-zA-Z]+\d*$', password) or
                re.match(r'^[a-zA-Z]+\d+$', password))


def check_character_diversity(password: str) -> dict:
    """Analyze character type distribution."""
    return {
        "lowercase": sum(1 for c in password if c in string.ascii_lowercase),
        "uppercase": sum(1 for c in password if c in string.ascii_uppercase),
        "digits":    sum(1 for c in password if c in string.digits),
        "special":   sum(1 for c in password if c in string.punctuation),
    }


def calculate_predictability_score(password: str) -> dict:
    """
    Calculate an overall predictability score (0-100).
    Higher score = MORE predictable = WEAKER password.
    """
    score = 0
    penalties = []
    bonuses = []

    # --- Length Check ---
    length = len(password)
    if length < 6:
        score += 40
        penalties.append(f"Very short length ({length} chars): +40")
    elif length < 8:
        score += 20
        penalties.append(f"Short length ({length} chars): +20")
    elif length < 12:
        score += 10
        penalties.append(f"Moderate length ({length} chars): +10")
    else:
        score -= 10
        bonuses.append(f"Good length ({length} chars): -10")

    # --- Common Password ---
    if check_common_password(password):
        score += 40
        penalties.append("Common password: +40")

    # --- Leet Speak Decoding ---
    decoded = check_leet_speak(password)
    if decoded != password.lower() and decoded in COMMON_PASSWORDS:
        score += 25
        penalties.append(f"Leet speak of common password ('{decoded}'): +25")

    # --- Keyboard Pattern ---
    if check_keyboard_pattern(password):
        score += 20
        penalties.append("Keyboard pattern detected: +20")

    # --- Repeated Characters ---
    repeat_ratio = check_repeated_chars(password)
    if repeat_ratio > 0.5:
        score += 20
        penalties.append(f"High character repetition ({repeat_ratio:.0%}): +20")
    elif repeat_ratio > 0.3:
        score += 10
        penalties.append(f"Moderate character repetition ({repeat_ratio:.0%}): +10")

    # --- Sequential Characters ---
    seq_count = check_sequential_chars(password)
    if seq_count >= 3:
        score += 15
        penalties.append(f"Many sequential characters ({seq_count} runs): +15")
    elif seq_count > 0:
        score += 5
        penalties.append(f"Some sequential characters ({seq_count} runs): +5")

    # --- Number Padding ---
    if check_number_padding(password):
        score += 10
        penalties.append("Simple number padding pattern: +10")

    # --- Character Diversity ---
    diversity = check_character_diversity(password)
    types_used = sum(1 for v in diversity.values() if v > 0)
    if types_used == 1:
        score += 20
        penalties.append("Only one character type used: +20")
    elif types_used == 2:
        score += 10
        penalties.append("Only two character types used: +10")
    elif types_used >= 4:
        score -= 10
        bonuses.append("All character types used: -10")

    # --- Entropy Bonus ---
    entropy = calculate_entropy(password)
    if entropy > 3.5:
        score -= 10
        bonuses.append(f"High Shannon entropy ({entropy}): -10")
    elif entropy < 2.0:
        score += 10
        penalties.append(f"Low Shannon entropy ({entropy}): +10")

    # Clamp score between 0 and 100
    score = max(0, min(100, score))

    return {
        "score": score,
        "penalties": penalties,
        "bonuses": bonuses,
    }


